from qgis.PyQt.QtWidgets import QAction
mw = iface.mainWindow()
results = []
for w in mw.findChildren(QAction):
    if w.objectName() == 'mActionShowTimeouts':
        panel = w.parent().metaObject().className()
        before = w.isChecked()
        if not w.isChecked():
            w.trigger()
        results.append({'panel': panel, 'before': before, 'after': w.isChecked()})
result = results
"}
